# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_deprecation() {
    printf '%s\t%s\n' \
        module:all 'Show deprecation warnings for all modules' \
        module:local 'Show deprecation warnings only for modules imported with a relative path' \
        module:none 'Drop all deprecation warnings'
}

_choice_output_name() {
    local -a chdir=()
    [[ -n "${argc_chdir:-}" ]] && chdir=(-chdir="$argc_chdir")
    tofu "${chdir[@]}" output -json 2>/dev/null | jq -b -r 'keys[]'
}

_choice_provider_address() {
    local -a chdir=()
    [[ -n "${argc_chdir:-}" ]] && chdir=(-chdir="$argc_chdir")
    tofu "${chdir[@]}" providers 2>/dev/null | sed -n 's/.*provider\[\([^]]*\)\].*/\1/p'
}

_choice_state_address() {
    local -a chdir=()
    [[ -n "${argc_chdir:-}" ]] && chdir=(-chdir="$argc_chdir")
    tofu "${chdir[@]}" state list 2>/dev/null || true
}

_choice_workspace() {
    local -a chdir=()
    [[ -n "${argc_chdir:-}" ]] && chdir=(-chdir="$argc_chdir")
    tofu "${chdir[@]}" workspace list 2>/dev/null | sed -n -e 's/^\* //p' -e 's/^  //p'
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
